pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testRegression_property() public {
        address target = address(new Target());
        bytes memory data = abi.encodeWithSignature("setStorage(uint256)", 42);
        bool ok;
        try c.forward(target, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Target {
    uint256 public stored;
    function setStorage(uint256 x) external {
        stored = x;
    }
}
